async def main() -> None:
    from datetime import date as date_type
    async with AsyncSessionLocal() as session:
        u_added = 0
        for u in UNIVERSITIES:
            r = await session.execute(text("SELECT id FROM universities WHERE name=:n LIMIT 1"), {"n": u["name"]})
            if r.scalar_one_or_none():
                continue
            session.add(University(
                id=uuid4(),
                name=u["name"],
                country=u["country"],
                city=u.get("city"),
                ranking=u.get("ranking"),
                website=u.get("website"),
                description=u.get("description"),
                tuition_fee=u.get("tuition_fee"),
                minimum_gpa=u.get("minimum_gpa"),
                minimum_ielts=u.get("minimum_ielts"),
                programs=u.get("programs", []),
                is_active=True,
                scholarships_available=True,
            ))
            u_added += 1

        s_added = 0
        for s in SCHOLARSHIPS:
            r = await session.execute(text("SELECT id FROM scholarships WHERE title=:t LIMIT 1"), {"t": s["title"]})
            if r.scalar_one_or_none():
                continue
            dl = None
            if s.get("deadline"):
                try:
                    dl = date_type.fromisoformat(s["deadline"])
                except Exception:
                    pass
            session.add(Scholarship(
                id=uuid4(),
                title=s["title"],
                provider=s.get("provider", ""),
                country=s.get("country"),
                amount=s.get("amount"),
                currency=s.get("currency", "USD"),
                degree_level=s.get("degree_level"),
                description=s.get("description"),
                eligibility=s.get("eligibility"),
                application_url=s.get("application_url"),
                deadline=dl,
                funding_type=s.get("funding_type"),
                is_active=True,
            ))
            s_added += 1

        await session.commit()
        print(f"Seeded: {u_added} universities, {s_added} scholarships.")


if __name__ == "__main__":
    asyncio.run(main())
